initJs:
function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = 'rank';
  let sortDirection = 'asc';

  // 店舗選択肢を初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const stores = tables[1]?.records || [];
    stores.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = store.店舗名;
        storeSelect.appendChild(option);
      }
    });
  }

  // 精度ランキングテーブルの再描画
  function renderRankingTable(data) {
    const tbody = container.querySelector('#ranking-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map((row, index) => {
      const accuracy = row.予測精度 || (100 - (row.MAPE || 0));
      const mapeColor = (row.MAPE || 0) > 20 ? '#dc3545' : (row.MAPE || 0) > 15 ? '#ff6a00' : '#28a745';
      const accuracyColor = accuracy < 80 ? '#dc3545' : accuracy < 90 ? '#ff6a00' : '#28a745';

      return `
        <tr data-id="${row.予測結果ID || row.id || index}">
          <td>${index + 1}</td>
          <td>${row.店舗名 || '不明'}</td>
          <td>${row.商品カテゴリ || '全般'}</td>
          <td style="color: ${mapeColor}; font-weight: bold;">${(row.MAPE || 0).toFixed(2)}%</td>
          <td>${(row.RMSE || 0).toFixed(2)}</td>
          <td style="color: ${accuracyColor}; font-weight: bold;">${accuracy.toFixed(1)}%</td>
          <td>${row.期間 || '過去1ヶ月'}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.予測結果ID || row.id || index}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 予測精度推移グラフの描画
  function drawAccuracyTrendChart() {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // サンプルデータ
    const dates = ['1週前', '6日前', '5日前', '4日前', '3日前', '2日前', '昨日'];
    const mapeData = [18.5, 17.2, 16.8, 15.9, 16.3, 15.7, 15.25];
    const rmseData = [9.2, 8.8, 8.5, 8.1, 8.3, 8.0, 8.42];

    // グラフエリア設定
    const padding = 60;
    const graphWidth = width - padding * 2;
    const graphHeight = height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // MAPE線の描画
    ctx.strokeStyle = '#007bff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < mapeData.length; i++) {
      const x = padding + (i * graphWidth) / (mapeData.length - 1);
      const y = height - padding - ((mapeData[i] - 10) / 15) * graphHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px sans-serif';
    ctx.fillText('MAPE (%)', padding, 20);
    ctx.fillStyle = '#007bff';
    ctx.fillRect(padding + 60, 12, 20, 12);
  }

  // 予測vs実績比較チャートの描画
  function drawForecastActualChart() {
    const canvas = container.querySelector('#forecast-actual-chart');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // サンプルデータ
    const dates = ['1週前', '6日前', '5日前', '4日前', '3日前', '2日前', '昨日'];
    const forecastData = [120, 135, 118, 142, 128, 155, 138];
    const actualData = [115, 140, 122, 138, 132, 148, 145];

    const padding = 60;
    const graphWidth = width - padding * 2;
    const graphHeight = height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // 予測値線の描画
    ctx.strokeStyle = '#007bff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < forecastData.length; i++) {
      const x = padding + (i * graphWidth) / (forecastData.length - 1);
      const y = height - padding - ((forecastData[i] - 100) / 60) * graphHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 実績値線の描画
    ctx.strokeStyle = '#28a745';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i * graphWidth) / (actualData.length - 1);
      const y = height - padding - ((actualData[i] - 100) / 60) * graphHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測値', padding, 20);
    ctx.fillStyle = '#007bff';
    ctx.fillRect(padding + 50, 12, 20, 12);
    ctx.fillStyle = '#d0e4ff';
    ctx.fillText('実績値', padding + 80, 20);
    ctx.fillStyle = '#28a745';
    ctx.fillRect(padding + 130, 12, 20, 12);
  }

  // データソート
  function sortData(data, column, direction) {
    return [...data].sort((a, b) => {
      let aVal = a[column] || 0;
      let bVal = b[column] || 0;

      if (typeof aVal === 'string') {
        aVal = aVal.toLowerCase();
        bVal = bVal.toLowerCase();
      }

      if (direction === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorContent = container.querySelector('#error-content');
    errorContent.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  // エラー非表示
  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.classList.add('hidden');
  }

  // CSVエクスポート
  function exportCSV() {
    if (!currentData || currentData.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['順位', '店舗名', '商品カテゴリ', 'MAPE (%)', 'RMSE', '予測精度 (%)', '期間'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentData.map((row, index) => [
        index + 1,
        `"${row.店舗名 || '不明'}"`,
        `"${row.商品カテゴリ || '全般'}"`,
        (row.MAPE || 0).toFixed(2),
        (row.RMSE || 0).toFixed(2),
        (row.予測精度 || (100 - (row.MAPE || 0))).toFixed(1),
        `"${row.期間 || '過去1ヶ月'}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `予測精度レポート_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // データ読み込み
  async function loadData() {
    try {
      hideError();
      const forecastData = await window.aivicApi.list(4); // 需要予測結果

      if (!forecastData) {
        showError('データの取得に失敗しました。ネットワーク接続を確認してください。');
        return;
      }

      // サンプルデータで補完
      const sampleData = [
        { 店舗名: '店舗A', 商品カテゴリ: '食品', MAPE: 15.25, RMSE: 8.42, 予測精度: 84.75, 期間: '過去1ヶ月' },
        { 店舗名: '店舗B', 商品カテゴリ: '日用品', MAPE: 12.80, RMSE: 6.15, 予測精度: 87.20, 期間: '過去1ヶ月' },
        { 店舗名: '店舗C', 商品カテゴリ: '衣料品', MAPE: 18.90, RMSE: 10.25, 予測精度: 81.10, 期間: '過去1ヶ月' },
        { 店舗名: '店舗A', 商品カテゴリ: '日用品', MAPE: 14.50, RMSE: 7.80, 予測精度: 85.50, 期間: '過去1ヶ月' },
        { 店舗名: '店舗B', 商品カテゴリ: '食品', MAPE: 16.75, RMSE: 9.20, 予測精度: 83.25, 期間: '過去1ヶ月' }
      ];

      currentData = sampleData;
      renderRankingTable(currentData);
      drawAccuracyTrendChart();
      drawForecastActualChart();

    } catch (error) {
      showError('データの読み込み中にエラーが発生しました: ' + error.message);
    }
  }

  // 初期化
  initStoreOptions();
  loadData();

  // 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const period = container.querySelector('#period-select').value;
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;

    try {
      hideError();
      await loadData();

      // フィルタリング処理
      let filteredData = [...currentData];

      if (storeId) {
        const selectedStore = tables[1]?.records?.find(s => s.店舗ID === storeId);
        if (selectedStore) {
          filteredData = filteredData.filter(d => d.店舗名 === selectedStore.店舗名);
        } else {
          showError('指定された店舗が見つかりません');
          return;
        }
      }

      if (category) {
        filteredData = filteredData.filter(d => d.商品カテゴリ === category);
      }

      currentData = filteredData;
      renderRankingTable(currentData);

    } catch (error) {
      showError('検索処理中にエラーが発生しました: ' + error.message);
    }
  });

  // エクスポートボタンのイベントリスナー
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 詳細分析ボタンのイベントリスナー
  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591838939'); // 需要予測管理画面
  });

  // 再試行ボタンのイベントリスナー
  container.querySelector('#btn-retry').addEventListener('click', loadData);

  // テーブルソート機能
  container.addEventListener('click', (e) => {
    const sortHeader = e.target.closest('.sortable');
    if (sortHeader) {
      const column = sortHeader.dataset.sort;
      if (sortColumn === column) {
        sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        sortColumn = column;
        sortDirection = 'asc';
      }

      const columnMap = {
        'rank': 'MAPE',
        'store': '店舗名',
        'category': '商品カテゴリ',
        'mape': 'MAPE',
        'rmse': 'RMSE',
        'accuracy': '予測精度',
        'period': '期間'
      };

      const sortedData = sortData(currentData, columnMap[column], sortDirection);
      renderRankingTable(sortedData);
    }

    // 詳細ボタンクリック
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1778591838939'); // 需要予測管理画面
    }
  });

  // オフライン状態の検出
  window.addEventListener('offline', () => {
    showError('ネットワークに接続できません。接続を確認してください。');
  });

  window.addEventListener('online', () => {
    hideError();
  });
}
